\label{thm gwp}
The equation \eqref{QNLS} with small initial data $u_0 \in \dot H^{-\frac12}(\mathbb{R}^3)$ is globally well-posed, scatters to free solutions, and has Lipschitz dependence on its initial data. The solution is also unique in the resolution space $\dot X^{-\frac12} \subset C_t \dot H^{-\frac12}$. 

Moreover, if the initial data is more regular, say $u_0 \in H^s(\mathbb{R}^3)$ for some $s>0$ and its critical norm $\|u_0\|_{\dot H^{-\frac12}(\mathbb{R}^3)}$ is small enough, then the global solution $u(t)$ preserves the regularity.

\label{Pref}
Let $M_1,M_2 \in (0,+\infty)$. For $k \in \mathbb{N}$, let $T_k : L^2(\mathbb{R}^n) \rightarrow L^2(\mathbb{R}^n)$ be a linear and bounded operator (acting spatially) such that
\[
M_1^{-1} \| \sum_{k \in \mathbb{N}}  T_k f \|_{L^2} \leq \left( \sum_{k \in \mathbb{N}}  \|T_k f \|^2_{L^2} \right)^\frac12 \leq M_2 \|f\|_{L^2}, \quad \forall f \in L^2.
\]
If $1 \leq p \leq 2$, then for all $u \in U^p$ we have the bound
\begin{equation} \label{U2dec}
\left( \sum_{k \in \mathbb{N}}  \|T_k u \|^2_{U^p} \right)^\frac12 \leq M_2 \|u\|_{U^p}.
\end{equation}
If $ p \geq 2$, then for all $v \in V^p$ we have the bound
\begin{equation} \label{V2dec}
 \| \sum_{k \in \mathbb{N}}  T_k v \|_{V^p}  \leq M_1 \left( \sum_{k \in \mathbb{N}}  \|T_k v \|^2_{V^p} \right)^\frac12. 
\end{equation}

\label{l2V2}
Assume that $v \in V^2$ is localized at frequency $2^k$ and we decompose
\[
v=\sum_{q \in \mathcal{C}_j} \chi_q(D_x) v
\]
for some $j \leq k$. If $q > 2$, then the following holds true
\begin{equation}
\sum_{q \in \mathcal{C}_k} \|\chi_q(D_x) v\|^2_{U^q} \lesssim \langle k-j \rangle^2 \|v\|_{V^2}^2. 
\end{equation}

We set $N \in \mathbb{N}$ such that $2N(1-\frac2q) \approx 3(k-j)$. 
We use the decomposition $v=u_N+v-u_N$ from \eqref{V2U2q}. From \eqref{U2dec}
we have that
\begin{equation} \label{aux1a}
\sum_{q \in \mathcal{C}_k} \|\chi_q(D_x) u_{N}\|^2_{U^2} \lesssim \|u_N\|_{U^2}^2.  
\end{equation}
On the other hand, for each $q$ it follows that
\[
\|\chi_q(D_x) (v-u_N)\|_{U^q} \lesssim \|v-u_N\|_{U^q} \lesssim \|v-u_N\|_{V^2}. 
\]
From this we obtain
\begin{equation} \label{aux1b}
\sum_{q \in \mathcal{C}_j} \|\chi_q(D_x) (v-u_N)\|^2_{U^q} \lesssim 2^{3(k-j)} 
 \|v-u_N\|_{U^q}^2 \lesssim 2^{2N(1-\frac2q)} \|v-u_N\|_{U^q} \lesssim \|v\|_{V^2}^2,
\end{equation}
given that the cardinality of cubes $q \in \mathcal{C}_j$ for which $\chi_q(D_x) (v-u_N)\neq 0$ is $\approx 2^{3(k-j)}$; here we implicitly use that $v$ and $u_N$ are localized at frequency $2^k$.  

The result of the Lemma then follows from \eqref{aux1a}, \eqref{aux1b}, and the inclusion $U^2 \subset U^q$.

\label{DualUV} If $1 < p,q< \infty, \frac1p+\frac1q=1$, the spaces $DU^p$ and $DV^p$ can be characterized as the space of distributions for which the following norms are finite:
\begin{equation} \label{TDU}
\|f\|_{DU^p}=\sup_{ \phi \in C_0^\infty: \| \phi\|_{V^q} \leq 1}  \left| \int \langle  f , \phi \rangle_{L^2} dt \right|,
\end{equation}
\begin{equation} \label{TDV}
\|f\|_{DV^p}=\sup_{ \phi \in C_0^\infty: \| \phi\|_{U^q} \leq 1}  \left| \int \langle  f , \phi \rangle_{L^2} dt \right|,
\end{equation}

\label{LDUD} If $1 < p,q< \infty, \frac1p+\frac1q=1$ the spaces $DU^p_\Delta$ and $DV^p_\Delta$ can be characterized as the space of distributions for which the following norms are finite:
\begin{equation} 
\|f\|_{DU^p_\Delta}=\sup_{ \phi \in C_0^\infty: \| \phi\|_{V^q_\Delta} \leq 1}  \left| \int \langle  f , \phi \rangle_{L^2} dt \right|,
\quad  
\|f\|_{DV^p}=\sup_{ \phi \in C_0^\infty: \| \phi\|_{U^q_\Delta} \leq 1}  \left| \int \langle  f , \phi \rangle_{L^2} dt \right|,
\end{equation}

\label{Ptri} 
For any $\epsilon>0$, the following hold true:
\begin{enumerate}[label=(\roman*)]
    \item If $k_3 > k_{min}$ or $|k_{min}-k_{max}| \leq 10 $,
    \begin{equation} \label{mtri}
        | \int u_{k_1} v_{k_2} \bar w_{k_3} dx dt| \leq C(\epsilon) 2^{\epsilon(k_{max}-k_{min})}
        2^{-\frac{k_{max}}2} \|u_{k_1}\|_{V^2_\Delta} \|v_{k_2}\|_{V^2_\Delta}  \|w_{k_3}\|_{V^2_\Delta};
    \end{equation}

    \item If $k_3=k_{min} \leq k_{max} -10$,
    \begin{equation} \label{mtri2}
        | \int u_{k_1} v_{k_2} \bar w_{k_3} dx dt| \leq C(\epsilon)  2^{(1-\epsilon)(k_{min}-k_{max})} 2^{-\frac{k_{max}}2} \|u_{k_1}\|_{V^2_\Delta} \|v_{k_2}\|_{V^2_\Delta}  \|w_{k_3}\|_{V^2_\Delta}.
    \end{equation}

    \item For all $k_1,k_2,k_3$,
    \begin{equation} \label{mtri3}
        | \int \bar u_{k_1} \bar v_{k_2} \bar w_{k_3} dx dt| \leq C(\epsilon)  2^{(1-\epsilon)(k_{min}-k_{max})} 2^{-\frac{k_{max}}2} \|u_{k_1}\|_{V^2_\Delta} \|v_{k_2}\|_{V^2_\Delta}  \|w_{k_3}\|_{V^2_\Delta}.
    \end{equation}

\end{enumerate}

\label{l:trihm}
The following holds true:
  \begin{equation} \label{trihmh}
    \| u \cdot Q_{\succeq 2k}v \cdot \bar w \|_{L^1} + \| u \cdot v \cdot
    \overline{ Q_{\succeq 2k} w} \|_{L^1} \lesssim 
    \langle k\rangle^2
    \|u\|_{V_{ \Delta }^{ 2 }} \|v\|_{V_{ \Delta }^{ 2 }} \|w\|_{ V_{ \Delta
    }^{ 2 }}, 
  \end{equation}
  \begin{equation} \label{trihml}
    \| Q_{\succeq 2k} u \cdot v \cdot \bar w \|_{L^1} 
    \lesssim \langle k \rangle^3  
    \|u\|_{ V_{ \Delta }^{ 2 }} 
    \|v\|_{ V_{ \Delta }^{ 2 }} 
    \|w\|_{ V_{ \Delta }^{ 2 }}.
  \end{equation}

\label{trilml} For any $\varepsilon>0$, there exists $C_\varepsilon>0$ such that the following holds true
\begin{equation}\label{eq transferred trilinear estimate}
| \int Q_{\prec 2k} u \cdot Q_{\prec 2k} v \cdot \overline{ Q_{\prec 2k} w} \ dx dt| 
\leq C_\varepsilon 2^{-k\varepsilon} \|u\|_{V_{ \Delta }^{ 2 }} \|v\|_{V_{ \Delta }^{ 2 }} \|w\|_{V_{ \Delta }^{ 2 }}.
\end{equation}

We use \eqref{V2bil} and \eqref{UVX} to obtain:
  \begin{align*}
      \lVert u v \overline{Q_{ \succeq 2k } w} \rVert _{ L^{ 1 } } 
    &\lesssim \lVert u v \rVert _{ L^{ 2 } } \lVert Q_{ \succeq 2k
    }w \rVert _{ L^{ 2 } } 
    \lesssim 2^{ k } \langle k \rangle^2 \lVert u \rVert _{ V_{ \Delta }^{ 2 } } 
    \lVert v \rVert _{ V_{ \Delta }^{ 2 } } 
    \cdot 2^{ -k } \lVert w \rVert_{ \dot X^{ 0,\frac{1}{2},\infty } }\\
    &\lesssim \langle k \rangle^2
    \lVert u \rVert _{ V_{ \Delta }^{ 2 } }
    \lVert v \rVert _{ V_{ \Delta }^{ 2 } }
    \lVert w \rVert _{ V_{ \Delta }^{ 2 } }.
  \end{align*}

Here the argument is a more complex.
There is an easy part, when the low frequency has a higher modulation localization. Indeed, using Bernstein, \eqref{V2Str} and \eqref{UVX}, we estimate as follows:
  \begin{equation} \label{easy}
  \begin{split}
    \left\lvert \int_{ \mathbb{R}^{ 1+3 } } Q_{ \succeq k }u v \bar w
      dx dt \right\rvert 
    &\lesssim \lVert  Q_{ \succeq k } u  \rVert_{ L^{ 2 }_{ t,x } } 
    \lVert \widetilde P_{ k } (v \bar w) \rVert_{ L_{ t,x }^{ 2 }  }
    \lesssim 2^{ -\frac{k}{2}  } \lVert u \rVert _{ \dot X^{ 0,\frac{1}{2}
      ,\infty } } 
      \cdot 2^{ \frac{k}{2}  } \lVert v \bar w \rVert _{ L_{ t }^{ 2 } L_{ x }^{
      \frac{3}{2} }  }\\
    &\lesssim \lVert u \rVert _{ V_{ \Delta }^{ 2 } } 
      \lVert v \rVert _{ L_{ t }^{ 4 } L_{ x }^{ 3 }  } 
      \lVert w \rVert _{ L_{ t }^{ 4 } L_{ x }^{ 3 }  } 
      \lesssim \lVert u \rVert_{ V_{ \Delta }^{ 2 } }
      \lVert v \rVert_{ V_{ \Delta }^{ 2 } }
      \lVert w \rVert_{ V_{ \Delta }^{ 2 } }.
      \end{split}
  \end{equation}
  For modulations $2k \preceq j \preceq k$ we change the strategy. Fix such a $j$. We notice that
  \[
  \int_{ \mathbb{R}^{ 1+3 } } Q_{ j }u \cdot v \bar w  d xd t 
  = \sum_{q,q' \in \mathcal{C}_k} \int Q_{ j }u \cdot v_q \bar w_{q'}  d xd t,
  \]
  where the sum is restricted to the pairs with $d(q,q') \lesssim 2^{k}$; here we use the notation $v_q = \chi_q(D) v$ for the component of $v$ with the property that $\hat v$ is localized in $q$, and similarly for $w_{q'}$. Then we fix such a pair $(q,q')$. We note that also have
  \[
  \int Q_{ j }u \cdot v_q \bar w_{q'}  d xd t = \sum_{I,I' \in \mathcal{I}_{j}} \int Q_{ j }u \cdot v_{q,I} \bar w_{q',I'},
  \]
where $ v_{q,I} = \chi_I(D_t) v_{q}$ is the component of $v_q$ with the property that $\hat v_q(\xi,\tau)$ has $\tau$ localization in $I$. Since $Q_j u$ is localized in the region $|\tau| \lesssim 2^j$, 
it suffices to restrict the summation over  pairs of intervals with the property $d(I,I') \lesssim 2^{j}$. We remark that, for a free solution
$(e^{-it\Delta} f)_q=e^{-it\Delta} f_q$, while the time frequency localization translates into $(e^{-it\Delta} f_q)_I= e^{-it\Delta} \chi_I(\xi^2) f_{q}$; essentially this produces a localization of $\xi$ in $S$, the strip characterized by $\xi^2 \in I$. This is a subset of the parallelepiped of size $C2^j \times C2^k \times C2^k$, where the size of $C2^j$ comes in the direction of $\xi_0$, where $\xi_0$ is the center of $q$.

\begin{lemma}\label{prop:ref-strichartz-2} 
i) Assume that $j \leq k \leq 0$ and $S$ is parallelepiped centered at $\xi_0$, $|\xi_0| \approx 1$ and of dimensions $ \approx 2^{ j }\times 2^{ k } \times 2^{ k }$. If $\hat f$ is supported in $S$, then
  \begin{align}\label{eq:slab-strichartz-2}
    \|e^{-it\Delta}f\|_{L_t^pL_x^q}
    \lesssim
    2^{\frac{2k+j}2 \left(1-\frac{2}{q}\right) - \frac{2k}{p}}
    \|f\|_{L_x^2}
  \end{align}
  whenever $2<p\leq\infty, \quad 2\leq q\leq\infty,\quad    \frac1p+\frac1q\leq\frac12$.
  In particular, $\|e^{-it\Delta}f\|_{L_{t,x}^4} \lesssim 2^{\frac{j}4}\|f\|_{L_x^2}$.

ii) Assume $u \in U^4_\Delta$ has similar localization properties. Then
\begin{equation}
\| u \|_{L^4_{t,x}} \lesssim 2^\frac{j}4 \|u\|_{U^4_\Delta}. 
\end{equation}

\end{lemma}

Assuming the above lemma, we conclude  the proof of \eqref{trihml}. For fixed pair $(q,q')$ and $I,I'$ we have
\begin{align*}
    \left\lvert \int_{ \mathbb{R}^{ 1+3 } } Q_{ j }u \cdot v_{q,I} \bar w_{q',I'}  d xd t \right\rvert
    &\lesssim \lVert Q_{ j }u  \rVert_{ L_{t,x}^{2 }}
      \lVert v_{q,I} \rVert_{ L_{ t,x }^{ 4 }  } \lVert w_{q',I'} \rVert_{ L_{ t,x } ^{ 4 }(T) }\\
    & \lesssim 2^{-\frac{j}2} \|u\|_{V^2_\Delta} 2^\frac{j}4 \|v_{q,I}\|_{U^4_\Delta} 2^\frac{j}4 \|w_{q',I'}\|_{U^4_\Delta} \\
& \lesssim  \|u\|_{V^2_\Delta} \|v_{q,I}\|_{U^4_\Delta} \|w_{q',I'}\|_{U^4_\Delta}. 
  \end{align*} 
Then we estimate the global term using Lemma \eqref{l2V2} as follows
\begin{align*}
    \left\lvert \int_{ \mathbb{R}^{ 1+3 } } Q_{ j }u \cdot v \bar w  d xd t \right\rvert
    & \lesssim \|u\|_{V^2_\Delta} \left(\sum_q \sum_I \|v_{q,I}\|^2_{U^4_\Delta} \right)^\frac12 \left( \sum_{q'} \sum_{I'} \|w_{q',I'}\|^2_{U^4_\Delta} \right)^\frac12 \\
    & \lesssim \|u\|_{V^2_\Delta} \langle j \rangle^2 \|v\|_{V^2_\Delta} \|w\|_{V^2_\Delta}.
  \end{align*} 
Strictly speaking, the result in Lemma \eqref{l2V2}, does not apply verbatim above, and requires some slight  adjustments. First, the localization of $\chi_q(D_x) \chi_I(D_t)$ is not entirely in spatial variables, as required by 
Lemma \eqref{l2V2}. However, recalling that we work with $Q_{\preceq 2k} v$ and $Q_{\preceq 2k} w$, then, just as we did for free solutions, this translates into a parallelepiped localization solely on the spatial variables. Second, the statement Lemma \eqref{l2V2} is made in terms of isotropic objects (cubes to be more precise), while here the localization is made on parallelepipeds. This is again not a problem, since the argument Lemma \eqref{l2V2} provides the argument in this setup as well, and we made sure we picked up the correct factor $\langle j \rangle$ since $2^j$ is the smallest scale that appears in the parallelepiped.


The summation over the range $2k \preceq j \preceq k$ of the above estimate, combined with \eqref{easy}, gives \eqref{trihml}. 

Thus we are left with establishing the claim in Lemma \ref{prop:ref-strichartz-2}, which we prove below.

\label{prop:ref-strichartz-2} 
i) Assume that $j \leq k \leq 0$ and $S$ is parallelepiped centered at $\xi_0$, $|\xi_0| \approx 1$ and of dimensions $ \approx 2^{ j }\times 2^{ k } \times 2^{ k }$. If $\hat f$ is supported in $S$, then
  \begin{align}\label{eq:slab-strichartz-2}
    \|e^{-it\Delta}f\|_{L_t^pL_x^q}
    \lesssim
    2^{\frac{2k+j}2 \left(1-\frac{2}{q}\right) - \frac{2k}{p}}
    \|f\|_{L_x^2}
  \end{align}
  whenever $2<p\leq\infty, \quad 2\leq q\leq\infty,\quad    \frac1p+\frac1q\leq\frac12$.
  In particular, $\|e^{-it\Delta}f\|_{L_{t,x}^4} \lesssim 2^{\frac{j}4}\|f\|_{L_x^2}$.

ii) Assume $u \in U^4_\Delta$ has similar localization properties. Then
\begin{equation}
\| u \|_{L^4_{t,x}} \lesssim 2^\frac{j}4 \|u\|_{U^4_\Delta}. 
\end{equation}

\label{ltri1}
Let $p>\frac{14}{15}$ and assume $f,g,h$ are frequency-localized as above. Then for any $\epsilon>0$ there exists $C_\epsilon>0$ such that
\begin{equation} \label{triro}
\|e^{-it\Delta} f \cdot e^{-it\Delta} g \cdot \overline{e^{-it\Delta} h} \|_{\ell^p_{\mathcal{P}} L^1} \leq C_\epsilon 2^{-k\epsilon} \|f\|_{L^2} \|g\|_{L^2} \|h\|_{L^2}.
\end{equation}

First, a standard argument (following \cite[Theorem 7]{Ca-note}) shows that \eqref{triro} can be generalized to functions in $U^2_\Delta$, that is
\begin{equation} \label{me1}
\|u \cdot v_q \cdot \bar w_{q'} \|_{\ell^p_{\mathcal{P}} L^1} \leq C_\epsilon 2^{-k\epsilon} \|u\|_{U^2_\Delta} \|v_q\|_{U^2_\Delta} \|w_{q'}\|_{U^2_\Delta},
\end{equation}
where, again, we assume all the localization mentioned above to be in place. We provide a complete proof of this transference in the appendix.

The second step in the transference is the following estimate in $U^a_\Delta$
\begin{equation}  \label{me2}
\| Q_{\prec 2k} u \cdot Q_{\prec 2k} v_q \cdot \overline{Q_{\prec 2k} w_{q'}} \|_{l^\infty_{\mathcal{P}} L^1} \leq C_\epsilon 2^{-k\epsilon} \|u\|_{U^a_\Delta} \|v_q\|_{U^a_\Delta} \|w_{q'}\|_{U^a_\Delta}, 
\end{equation}
for any $2 \leq a < \infty$. To prove this we use the following linear estimate: if $I$ is a time interval of length $\approx 2^{-2k}$ and $\varphi_I$ is a bump function adapted to $I$, then
\begin{equation} \label{sme}
\| \varphi_I Q_{\prec 2k} z \|_{X^{0,\frac12,1}} \lesssim \| z \|_{U^a_\Delta},
\end{equation}
The proof can be found in \cite[Lemma 5.5]{Be-rs} combined with the embedding $U^a_\Delta \subset L^\infty_t L^2_x$. This estimate allows us to treat each of the terms $Q_{\prec 2k} u$, $Q_{\prec 2k} v_q$, $Q_{\prec 2k} w_{q'}$ as elements of $X^{0,\frac12,1}$ when restricted to a single parallelepiped $P$. Since $X^{0,\frac12,1} \subset U^2_\Delta$, we then invoke \eqref{me1} to obtain \eqref{me2}.

Next, we interpolate between \eqref{me1} (with some $\frac{14}{15}<p<1$) and \eqref{me2} to obtain
\begin{equation} \label{mef}
\|Q_{\prec 2k} u \cdot Q_{\prec 2k} v_q \cdot \overline{Q_{\prec 2k} w_{q'}} \|_{l^1_{\mathcal{P}} L^1} \leq C_\epsilon 2^{-k\epsilon} \|u\|_{U^a_\Delta} \|v_q\|_{U^a_\Delta} \|w_{q'}\|_{U^a_\Delta},
\end{equation}
where $a=\frac{2}{p}>2$. The formalization of this interpolation can be found in the proof of Theorem 1.7 in \cite{Ca}


This gives the correct global bound in $L^1$. The next step is the summation with respect to the cubes $q,q'$. Here we have
\[
\begin{split}
|I| \leq C_\epsilon 2^{-k\epsilon} \sum_{q,q' \in \mathcal{C}_k} \|u\|_{U^a_\Delta} \|v_q\|_{U^a_\Delta} \|w_{q'}\|_{U^a_\Delta}
\lesssim \|u\|_{U^a_\Delta} \left( \sum_{q \in \mathcal{C}_k}  \|v_q\|_{U^a_\Delta}^2 \right)^\frac12
\left( \sum_{q' \in \mathcal{C}_k}  \|w_{q'}\|_{U^a_\Delta}^2 \right)^\frac12,
\end{split}
\]
where this was possible because the sum $\sum_{q,q' \in \mathcal{C}_k}$ is restricted over cubes with the property $d(q,q') \lesssim 2^k$. Invoking Lemma \ref{l2V2} and the embedding $V^2_\Delta\subset U^a_\Delta$ allows us to conclude
\[
|I| \leq C_\epsilon 2^{-k\epsilon} \langle k \rangle^2 \|u\|_{V^2_\Delta} \|v\|_{V^2_\Delta} \|w\|_{V^2_\Delta} \lesssim C_\epsilon 2^{-k\epsilon} \|u\|_{V^2_\Delta} \|v\|_{V^2_\Delta} \|w\|_{V^2_\Delta}
\]
which proves Theorem \ref{trilml} with an acceptable subpolynomial loss.

Let $p>\frac{14}{15}$. Let $\mathbb{P}=\{(\xi,|\xi|^2): \xi \in \mathbb{R}^3\}$ denote the paraboloid in $\mathbb{R}^4$ and let $S_i=\mathbb{P}\cap B_1(x_i)$ where $\@ifstar{\@ifstar{\@ifstar{\@ifstar{\abs}{\abs*}}{\@ifstar{\abs}{\abs*}*}}{\@ifstar{\@ifstar{\abs}{\abs*}}{\@ifstar{\abs}{\abs*}*}*}}{\@ifstar{\@ifstar{\@ifstar{\abs}{\abs*}}{\@ifstar{\abs}{\abs*}*}}{\@ifstar{\@ifstar{\abs}{\abs*}}{\@ifstar{\abs}{\abs*}*}*}*}{x_1},\@ifstar{\@ifstar{\@ifstar{\@ifstar{\abs}{\abs*}}{\@ifstar{\abs}{\abs*}*}}{\@ifstar{\@ifstar{\abs}{\abs*}}{\@ifstar{\abs}{\abs*}*}*}}{\@ifstar{\@ifstar{\@ifstar{\abs}{\abs*}}{\@ifstar{\abs}{\abs*}*}}{\@ifstar{\@ifstar{\abs}{\abs*}}{\@ifstar{\abs}{\abs*}*}*}*}{x_2}\leq 8$ and $\@ifstar{\@ifstar{\@ifstar{\@ifstar{\abs}{\abs*}}{\@ifstar{\abs}{\abs*}*}}{\@ifstar{\@ifstar{\abs}{\abs*}}{\@ifstar{\abs}{\abs*}*}*}}{\@ifstar{\@ifstar{\@ifstar{\abs}{\abs*}}{\@ifstar{\abs}{\abs*}*}}{\@ifstar{\@ifstar{\abs}{\abs*}}{\@ifstar{\abs}{\abs*}*}*}*}{x_3}\approx 2^{-k}$ such that they satisfy \eqref{ndeg} with $\nu\approx 1$, that is
\begin{align*}
    \@ifstar{\@ifstar{\@ifstar{\@ifstar{\abs}{\abs*}}{\@ifstar{\abs}{\abs*}*}}{\@ifstar{\@ifstar{\abs}{\abs*}}{\@ifstar{\abs}{\abs*}*}*}}{\@ifstar{\@ifstar{\@ifstar{\abs}{\abs*}}{\@ifstar{\abs}{\abs*}*}}{\@ifstar{\@ifstar{\abs}{\abs*}}{\@ifstar{\abs}{\abs*}*}*}*}{N(\zeta_1)\wedge N(\zeta_2) \wedge N(\zeta_3)} \gtrsim 1\quad\forall \zeta_i\in S_i.
\end{align*}
Let $\mathcal{E}_i$ denote the extension operator associated to each $S_i$. Then for all $\epsilon>0$ there exists $C_\epsilon>0$ such that
\begin{align}
    \| \prod_{i=1}^3  \tilde{\mathcal{E}}_i f_i\|_{\ell^p_\mathcal{P} L^{1}} \leq C_\epsilon 2^{-k\epsilon} \prod_{i=1}^3 \|f_i\|_{L^2}.
\end{align}
